# Loaded before anything else so that the sidebar footer, the exports, and the
# report template all read the same release string.
app_name <- "Daybreak"

# Small header controls live here so the page layout below stays readable.
palette_button <- function(name, label, colors, pressed = FALSE) {
  tags$button(
    type = "button", class = "palette-option", `data-palette` = name,
    `aria-pressed` = tolower(as.character(pressed)),
    `aria-label` = paste("Use", label, "palette"),
    span(class = "swatches", lapply(colors[1:4], function(color) tags$i(style = sprintf("--swatch:%s", color)))),
    span(class = "palette-name", label)
  )
}

